{ echo '<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">'; sed -e 's/id="switch" data-on="false"/id="switch" data-on="true"/' -e 's#<i class="st">isolated</i>#<i class="st">connected</i>#g' -e 's#Three university units, three separate assignments. Illustrative · not data from a real candidate.#<b>Connected.</b> One robot through three units: sensors feed Python, Python feeds the backend, the backend survives 5,000 pretend robots on Azure. Illustrative · not data from a real candidate.#' "Manit Khera Portfolio.html"; echo '</html>'; } > _print.html
